SELECT
    t.task_id,
    t.title,
    t.status,
    t.deadline,
    t.completion_mode,
    t.creator_id AS creatorId,
    t.update_time,
    (SELECT COUNT(1) FROM t_task_participant tp
      WHERE tp.task_id = t.task_id AND tp.deleted_flag = #{param.deletedFlag}) AS participantCount,
    (SELECT COUNT(1) FROM t_task_participant td
      WHERE td.task_id = t.task_id AND td.deleted_flag = #{param.deletedFlag}
        AND td.status = #{param.doneParticipantStatus}) AS doneCount,
    (SELECT tm.status FROM t_task_participant tm
      WHERE tm.task_id = t.task_id AND tm.member_id = #{param.memberId}
        AND tm.deleted_flag = #{param.deletedFlag} LIMIT 1) AS myStatus,
    (CASE WHEN t.deadline < #{param.now}
           AND t.status IN
           #{activeStatus}
          THEN 1 ELSE 0 END) AS overdueFlag
FROM t_task t
WHERE t.deleted_flag = #{param.deletedFlag}



        AND t.creator_id = #{param.memberId}



        AND EXISTS (SELECT 1 FROM t_task_participant me
                     WHERE me.task_id = t.task_id AND me.member_id = #{param.memberId}
                       AND me.deleted_flag = #{param.deletedFlag})



    AND t.status = #{param.query.status}


    AND t.status IN
    #{overdueStatus}
    AND t.deadline < #{param.now}


    AND INSTR(t.title, #{param.query.keyword})



    AND t.create_time >= #{param.createStartTime}

ORDER BY t.update_time DESC, t.task_id DESC

SELECT

FROM t_task
WHERE task_id = #{taskId}
AND deleted_flag = #{deletedFlag}

