AND deleted_flag = 0
AND status IN

    #{expectStatus}

mapper.select:
SELECT
    (SELECT COUNT(1)
       FROM t_task_participant p
       INNER JOIN t_task t ON p.task_id = t.task_id
      WHERE p.member_id = #{memberId}
        AND p.deleted_flag = #{deletedFlag}
        AND p.status IN
        #{pStatus}
        AND t.deleted_flag = #{deletedFlag}
        AND t.status IN
        #{tStatus}) AS assigneeCount,
    (SELECT COUNT(1)
       FROM t_task c
      WHERE c.creator_id = #{memberId}
        AND c.deleted_flag = #{deletedFlag}
        AND c.status IN
        #{cStatus}) AS creatorCount,
    (SELECT COUNT(1)
       FROM t_task_participant p2
       INNER JOIN t_task t2 ON p2.task_id = t2.task_id
      WHERE p2.member_id = #{memberId}
        AND p2.deleted_flag = #{deletedFlag}
        AND p2.status IN
        #{p2Status}
        AND t2.deleted_flag = #{deletedFlag}
        AND t2.status IN
        #{t2Status}
        AND t2.deadline < #{now}) AS overdueCount

SELECT DISTINCT m.member_id AS memberId, m.nickname, m.avatar
FROM t_task_participant p
INNER JOIN t_task t ON p.task_id = t.task_id
INNER JOIN t_wx_member m ON m.member_id = t.creator_id
WHERE p.member_id = #{memberId}
  AND p.deleted_flag = #{deletedFlag}
  AND p.status IN
  #{pStatus}
  AND t.deleted_flag = #{deletedFlag}
  AND t.status IN
  #{tStatus}
  AND t.creator_id <> #{memberId}
ORDER BY m.member_id DESC
LIMIT #{limit}

SELECT
    (SELECT COUNT(1) FROM t_task tc
      WHERE tc.creator_id = #{memberId} AND tc.deleted_flag = #{deletedFlag}) AS sentCount,
    (SELECT COUNT(1) FROM t_task_participant p
      WHERE p.member_id = #{memberId} AND p.deleted_flag = #{deletedFlag}) AS receivedCount,
    (SELECT COUNT(1) FROM t_task_participant pd
      WHERE pd.member_id = #{memberId} AND pd.deleted_flag = #{deletedFlag}
        AND pd.status = #{doneStatus}) AS completedCount,
    (SELECT COUNT(1)
       FROM t_task_participant pon
       INNER JOIN t_task ton ON pon.task_id = ton.task_id
      WHERE pon.member_id = #{memberId}
        AND pon.deleted_flag = #{deletedFlag}
        AND pon.status = #{doneStatus}
        AND ton.deleted_flag = #{deletedFlag}
        AND pon.complete_time <= ton.deadline) AS onTimeCount

SELECT

FROM t_task
WHERE deleted_flag = 0
AND status = #{scheduledStatus}
AND start_time IS NOT NULL
AND start_time <= #{now}
ORDER BY start_time ASC
LIMIT #{limit}

SELECT

FROM t_task
WHERE deleted_flag = #{deletedFlag}
AND remind_time IS NOT NULL
AND remind_time <= #{now}
ORDER BY remind_time ASC
LIMIT #{limit}

SELECT

FROM t_task
WHERE deleted_flag = #{deletedFlag}
AND status = #{status}
AND deadline < #{now}
AND deadline >= #{since}
ORDER BY deadline ASC
LIMIT #{limit}

